import pandas as pd
import json
import numpy as np
datasets = ['data/bace.csv','data/bbbp.csv','data/clintox.csv','data/hiv.csv','data/muv.csv']
stats = {}
for f in datasets:
    df = pd.read_csv(f)
    name = f.split('/')[-1][:-4]
    stats[name] = {'n_samples': int(df.shape[0]), 'columns': list(df.columns)}
    numeric_cols = df.select_dtypes(include=[np.number]).columns.tolist()
    label_cols = [c for c in numeric_cols if c not in ['ID','CID','mol_id','num']]
    stats[name]['labels'] = {}
    for lc in label_cols:
        pos = int((df[lc] == 1).sum())
        neg = int(df.shape[0] - pos)
        balance = float(pos / df.shape[0])
        stats[name]['labels'][lc] = {'positive': pos, 'negative': neg, 'balance': balance}
print(json.dumps(stats, indent=2))
" > outputs/data_stats.json"
